import {patchMarkup} from './dom-patch.js';
import {MISSIONS,EQUIPMENT,DEFAULT_DESIGN,SAVE_KEY,PROGRESS_KEY,PHASE_NAMES,evaluateDesign,createCampaign,objectives,canAction,startAction,completeAction,tickCampaign,powerStatus,contactOpen,abortCampaign,campaignReport,encodeSave,decodeSave} from './campaign-core.js';
import {createCampaignWorld} from './campaign-world.js';
import {mountPreferences} from './preferences.js';
import {openRepair} from './repairs-ui.js';

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ROOM={cockpit:'Flight deck',lab:'Science laboratory',power_room:'Power room',life_support:'Life support',workshop:'Workshop',engine_bay:'Engine bay',airlock:'Airlock',exterior:'Telescope instrument bay'};
const CLOCK=s=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

export function initCampaign(api, options={}){
 const root=document.createElement('section');root.id='campaign';root.hidden=true;document.body.append(root);
 let state=null,world=null,view='select',definition=MISSIONS[0],design={...DEFAULT_DESIGN},progress={},saved=null,checkpoint=null;
 let modal=false,paused=false,loading=false,loadToken=0,last=performance.now(),accumulator=0,hudTime=0,saveTime=0,notice='',noticeTime=0,repairClose=null;
 let context={room:'cockpit',near:false},tuning={alignment:20,closure:65,calibration:25},renderedPhase='',recorded=false;
 const read=(key)=>{try{return localStorage.getItem(key);}catch{return null;}};
 try{const x=JSON.parse(read(PROGRESS_KEY)||'{}');if(x&&typeof x==='object'&&!Array.isArray(x))progress=x;}catch{}
 saved=decodeSave(read(SAVE_KEY));
 const store=(key,value)=>{try{localStorage.setItem(key,value);return true;}catch{notice='Browser storage is unavailable. Keep this tab open to finish the mission.';noticeTime=8;return false;}};
 const notify=text=>{notice=text;noticeTime=5;const el=root.querySelector('.cp-toast');if(el)el.textContent=text;};
 const button=(label,attr='',cls='cp-button')=>`<button class="${cls}" ${attr}>${label}</button>`;
 const header=()=>`<header class="cp-header"><a href="#" data-cp="missions" class="cp-brand">T<span>−</span>MINUS<small>THE FIRST FRONTIER</small></a><span class="cp-tag">SINGLE PLAYER / CAMPAIGN</span>${button('MAIN MENU','data-cp="exit"','cp-quiet')}</header>`;
 function open(){root.hidden=false;document.body.classList.add('campaign-active');api.crewExperience?.planningChanged(true);api.mission.paused=true;document.exitPointerLock?.();select();}
 function exit(){loadToken++;loading=false;repairClose?.();repairClose=null;modal=false;if(state&&!['complete','failed','aborted'].includes(state.phase))save();world?.dispose();world=null;root.hidden=true;document.body.classList.remove('campaign-active');state=null;view='select';api.crewExperience?.planningChanged(false);}
 function select(){view='select';paused=true;world?.setPaused(true);saved=decodeSave(read(SAVE_KEY));root.innerHTML=`${header()}<main class="cp-select"><div class="cp-intro"><div class="cp-eyebrow">CAMPAIGN / CHAPTER ONE</div><h1>THE FIRST<br><em>FRONTIER.</em></h1><p>Design the spacecraft. Work as a crew.<br>Bring the mission home.</p><div class="cp-program"><span class="cp-orbit-icon">◎</span><div><b>A new space program starts with you.</b><p>Ines Valder / Mission Director</p></div></div>${saved&&!['complete','failed','aborted'].includes(saved.phase)?button('CONTINUE MISSION →','data-cp="continue"','cp-button cp-primary'):''}<p class="cp-small">Two playable missions. Additional chapters are planned.<br>Progress is saved in this browser.</p><p class="cp-small">The source files are included in the downloaded release archive.</p></div><div class="cp-mission-list">${MISSIONS.map((m,i)=>{const locked=m.id==='telescope'&&!progress.orbital;return `<button class="cp-mission ${!m.available?'cp-future':''}" data-mission="${m.id}" ${!m.available||locked?'disabled':''}><span class="cp-mission-number">${m.number}</span><div><small>${m.available?locked?'COMPLETE MISSION 01 TO UNLOCK':progress[m.id]?'COMPLETED / REPLAY AVAILABLE':m.destination:'FUTURE CHAPTER'}</small><h2>${m.name}</h2>${m.available?`<p>${m.summary}</p><span>${m.duration} · ${progress[m.id]?'BEST '+progress[m.id].score+' PTS':'SOLO + CREW ASSISTANCE'}</span>`:''}</div><b>${!m.available||locked?'◇':'↗'}</b></button>`;}).join('')}</div></main>`;}
 function briefing(id){definition=MISSIONS.find(m=>m.id===id&&m.available);if(!definition)return;if(id==='telescope'&&!progress.orbital){notify('Complete First Orbital Flight to unlock this mission.');return;}design={...DEFAULT_DESIGN};view='briefing';root.innerHTML=`${header()}<main class="cp-brief"><div class="cp-eyebrow">MISSION ${definition.number} / BRIEFING</div><h1>${definition.name}</h1><p class="cp-lead">${definition.summary}</p><div class="cp-brief-grid"><article class="cp-panel"><small>COMMANDER INES VALDER</small><h2>“Every choice flies with you.”</h2><p>${definition.id==='orbital'?'We have one spacecraft and one chance to prove our program can work in orbit. Check your systems, collect the observations, and keep enough energy to bring everyone home.':'The observatory is waiting. Match its orbit, prepare your equipment, and replace the instrument. Out there, the tether is your way home.'}</p><h3>SUCCESS CRITERIA</h3><ul><li>Complete spacecraft checkout and orbital insertion.</li>${definition.id==='telescope'?'<li>Install a replacement telescope instrument and return through the airlock.</li>':''}<li>Collect and transmit at least 90 MB of observations.</li><li>Recover the laboratory electrical circuit.</li><li>Complete the guided return safely.</li></ul></article><article class="cp-panel"><small>MISSION NOTES</small><h2>${definition.destination}</h2><p>Approximate playtime: ${definition.duration.toLowerCase()}. Progress follows your actions; take time to learn the ship.</p><p>WASD move · mouse look · E operate nearby station · V camera · Escape pause. During EVA: Space up, Control down.</p><p>Follow the illuminated console in the indicated room. Equipment tasks take place at that station.</p><h3>HISTORICAL INSPIRATION</h3><p>${definition.reference}</p><p class="cp-small">Illustrative equipment values. Guided orbital flight, time compression and simplified EVA are disclosed gameplay abstractions.</p></article></div><div class="cp-actions">${button('← MISSION SELECT','data-cp="missions"')}${button('DESIGN SPACECRAFT →','data-cp="design"','cp-button cp-primary')}</div></main>`;}
 function renderDesign(){view='design';const e=evaluateDesign(design,definition.id);root.innerHTML=`${header()}<main class="cp-design"><div class="cp-eyebrow">MISSION ${definition.number} / ENGINEERING</div><h1>BUILD YOUR<br><em>MISSION MARGIN.</em></h1><p class="cp-lead">The hardware you choose determines your spacecraft’s live capabilities.</p><div class="cp-design-grid"><div class="cp-components">${Object.entries(EQUIPMENT).map(([key,options])=>`<fieldset><legend>${key.toUpperCase()}</legend><div>${options.map(p=>`<button data-equipment="${key}" data-value="${p.id}" class="cp-part ${design[key]===p.id?'selected':''}" aria-pressed="${design[key]===p.id}"><b>${p.name}</b><span>${p.mass} kg · ${p.cost} credits</span><small>${p.wh?p.wh+' Wh reserve':p.watts?p.watts+' W '+(key==='array'?'generation':'draw'):p.rate+' MB/s downlink'}</small></button>`).join('')}</div></fieldset>`).join('')}</div><aside class="cp-panel cp-readiness"><small>LIVE READINESS / ${definition.name}</small><div class="cp-status ${e.valid?'go':'nogo'}">${e.valid?'GO FOR REVIEW':'NO-GO'}</div><div class="cp-metric"><span>Wet mass</span><b>${e.mass} / 850 kg</b></div><div class="cp-metric"><span>Budget</span><b>${e.cost} / ${e.budget} credits</b></div><div class="cp-metric"><span>Science load</span><b>${e.load} W</b></div><div class="cp-metric"><span>Solar generation</span><b>${e.parts.array.watts} W</b></div><div class="cp-metric"><span>Eclipse science endurance</span><b>${Math.round(e.parts.battery.wh/e.load*3600/8)} play seconds</b></div>${e.errors.map(x=>`<p class="cp-error">${x}</p>`).join('')}${e.warnings.map(x=>`<p class="cp-warning">${x}</p>`).join('')}<p class="cp-small">Fictional training hardware. Essential load: 800 W, or 600 W in conservation mode. Resource simulation advances 8 seconds per play second. Eclipse lasts at least 180 play seconds; optional work can extend it.</p><p class="cp-small">This campaign’s crewed spacecraft configuration is independent of the existing Mission Control survey-bus simulator.</p>${button('ACCEPT DESIGN & BOARD →','data-cp="board" '+(!e.valid?'disabled':''),'cp-button cp-primary')}</aside></div></main>`;}
 function save(isCheckpoint=false){if(!state)return;const raw=encodeSave(state);store(SAVE_KEY,raw);saved=decodeSave(raw);if(isCheckpoint||!checkpoint)checkpoint=raw;}
 async function board(restored=null){if(loading)return;loading=true;const token=++loadToken;try{state=restored||createCampaign(definition.id,design);definition=MISSIONS.find(m=>m.id===state.missionId);design={...state.design};recorded=false;view='loading';root.innerHTML=`${header()}<div class="cp-loading"><span>◎</span><h2>BOARDING THE SPACECRAFT</h2><p>Preparing the interior, navigation and equipment…</p></div>`;world?.dispose();world=null;root.insertAdjacentHTML('beforeend','<canvas class="cp-canvas" tabindex="0" aria-label="Explorable campaign spacecraft"></canvas>');const canvas=root.querySelector('canvas');const next=await (options.createWorld||createCampaignWorld)(canvas,{ship:api.ship,getPhase:()=>state?.phase,isBlocked:()=>paused||modal||view!=='play',interact:()=>interact(),onContext:c=>context=c});if(token!==loadToken){next.dispose();return;}world=next;paused=false;modal=false;view='play';renderedPhase='';last=performance.now();accumulator=0;saveTime=0;world.setEVA(state.phase==='eva');root.querySelector('.cp-loading')?.remove();root.querySelector('.cp-header')?.remove();root.insertAdjacentHTML('beforeend','<div class="cp-hud"></div><div class="cp-overlay" hidden></div>');save();renderHUD();notify('Ines: Welcome aboard. Visit the marked room consoles and press E.');}catch(e){if(token!==loadToken)return;view='error';root.innerHTML=`${header()}<main class="cp-brief"><h1>Boarding interrupted</h1><p>${esc(e.message)}</p>${button('RETRY BOARDING','data-cp="retry"')}${button('MISSION SELECT','data-cp="missions"')}</main>`;}finally{if(token===loadToken)loading=false;}}
 function activeObjective(){const list=objectives(state);return list.find(a=>a.room===context.room&&a.id!=='wait')||list[0];}
 function interact(id){if(!state||paused||modal||view!=='play')return;const a=id?objectives(state).find(a=>a.id===id):activeObjective();if(!a||a.id==='wait')return;if(!context.near){notify('Move close to the illuminated room console.');return;}const reason=canAction(state,a.id,context.room,{...context,...tuning});if(reason){notify(reason);return;}
  if(a.id==='fuse'){modal=true;world.setPaused(true);const e=evaluateDesign(state.design,state.missionId);repairClose=openRepair(root,'fuse',{power:{loadKW:e.load/1000}},Math.round(state.elapsed)+7,result=>{if(result.ok){completeAction(state,'fuse');save();}},()=>{modal=false;world?.setPaused(false);repairClose=null;renderHUD();});return;}
  const result=startAction(state,a.id,context.room,{...context,...tuning});if(!result.ok)notify(result.reason);else notify(a.seconds?`${a.label} — stay at this station.`:a.label);renderHUD();
 }
 function renderHUD(){if(view!=='play'||!state||!world)return;const hud=root.querySelector('.cp-hud');if(!hud)return;const e=evaluateDesign(state.design,state.missionId),p=powerStatus(state),list=objectives(state),next=activeObjective();const changed=renderedPhase!==state.phase;renderedPhase=state.phase;
  const tuningMarkup=state.phase==='rendezvous'?`<label>ALIGNMENT / target 50<input data-tuning="alignment" type="range" min="0" max="100" value="${tuning.alignment}"><output>${tuning.alignment}</output></label><label>CLOSURE / target 30<input data-tuning="closure" type="range" min="0" max="100" value="${tuning.closure}"><output>${tuning.closure}</output></label>`:state.phase==='science'&&!state.calibrated?`<label>CALIBRATION / target 50<input data-tuning="calibration" type="range" min="0" max="100" value="${tuning.calibration}"><output>${tuning.calibration}</output></label>`:'';
  // patchMarkup retains focused sliders while room objectives and telemetry update.
  patchMarkup(hud,`<div class="cp-flight-top"><div class="cp-brand">T<span>−</span>MINUS<small>MISSION ${definition.number} / ${esc(definition.name)}</small></div><div class="cp-flight-phase"><small>${PHASE_NAMES[state.phase]}</small><b>T+${CLOCK(state.elapsed)}</b></div>${button('PAUSE / ESC','data-cp="pause"','cp-quiet')}</div><aside class="cp-objectives"><small>MISSION OBJECTIVES</small><h2>${PHASE_NAMES[state.phase]}</h2>${list.map(a=>`<div class="cp-objective ${a.room===context.room?'here':''}"><i>${a.room===context.room?'◉':'○'}</i><div><b>${a.label}</b><span>${ROOM[a.room]||a.room}${a.seconds?' · '+a.seconds+' SEC':''}</span></div></div>`).join('')}<p>${state.phase==='eclipse'?state.fault?'Laboratory circuit offline. Isolate before replacing the fuse.':'Eclipse exit in '+Math.max(0,Math.ceil(180-state.phaseTime))+' seconds. Optional science uses battery energy.':state.phase==='downlink'?contactOpen(state)?'Ground contact active. Transmission requires the laboratory console.':'Ground contact in '+Math.ceil(30-state.phaseTime%90)+' seconds.':state.phase==='launch'||state.phase==='reentry'?'Guided sequence completes in '+Math.max(0,Math.ceil(45-state.phaseTime))+' seconds.':'Move to an illuminated console in the required room.'}</p></aside><aside class="cp-resources"><small>SPACECRAFT / LIVE</small><div class="cp-metric"><span>Battery</span><b class="${state.energy/p.capacity<.25?'cp-warning':''}">${Math.round(state.energy/p.capacity*100)}%</b></div><div class="cp-meter"><i style="width:${state.energy/p.capacity*100}%"></i></div><div class="cp-metric"><span>Generation / draw</span><b>${p.generation} / ${p.load} W</b></div><div class="cp-metric"><span>Stored observations</span><b>${Math.round(state.stored)} / 240 MB</b></div><div class="cp-metric"><span>Received on Earth</span><b>${Math.floor(state.transmitted)} / 90 MB</b></div><div class="cp-metric"><span>Power circuit</span><b>${state.fault?'OFFLINE':'NOMINAL'}</b></div>${button(state.conserve?'CONSERVATION ON':'CONSERVE ESSENTIAL POWER','data-cp="conserve"','cp-quiet')}<p class="cp-small">8× resource time · fictional training values</p></aside><div class="cp-deck">${['engine_bay','power_room','life_support','workshop','lab','cockpit'].map(r=>`<span class="${context.room===r?'current':next?.room===r?'target':''}">${ROOM[r]}</span>`).join('<i>›</i>')}<span class="${context.room==='airlock'?'current':''}">↳ Airlock / Workshop</span></div><div class="cp-crosshair">+</div><div class="cp-location"><small>CURRENT MODULE</small><b>${ROOM[context.room]||'Connecting hatch'}</b><span>${state.phase==='eva'?'SPACE / CTRL  VERTICAL · 16 M SAFETY TETHER':'WASD MOVE · MOUSE LOOK · V CAMERA'}</span></div><section class="cp-station"><small>${context.near?'STATION IN REACH':'APPROACH THE ROOM CONSOLE'}</small>${tuningMarkup}<div class="cp-station-actions">${list.filter(a=>a.room===context.room&&a.id!=='wait').map(a=>button(`${a.id===next?.id?'[E] ':''}${a.label}`,`data-task="${a.id}" ${!context.near||state.activity?'disabled':''}`,'cp-button cp-primary')).join('')||`<p>${next?`Next: ${esc(next.label)} → ${ROOM[next.room]||next.room}`:'Follow the mission checklist.'}</p>`}</div>${state.activity?`<div class="cp-task-progress"><b>${Math.ceil(state.activity.remaining)} SEC / WORKING</b><div class="cp-meter"><i style="width:${(1-state.activity.remaining/state.activity.total)*100}%"></i></div>${button('CANCEL TASK','data-cp="cancel-task"','cp-quiet')}</div>`:''}</section><div class="cp-crew"><b>CREW ASSISTANCE</b><span>Finn / orientation · Chip / power · Barbara / communications · Fernando / science</span><select data-crew aria-label="Assign supporting crew"><option value="monitor" ${state.crewCommand==='monitor'?'selected':''}>Monitor reserves / auto-conserve</option><option value="orientation" ${state.crewCommand==='orientation'?'selected':''}>Pilot / precise pointing (+10% data)</option><option value="prepare" ${state.crewCommand==='prepare'?'selected':''}>Specialist / prepare EVA or secure lab</option></select></div><div class="cp-toast" role="status">${noticeTime>0?esc(notice):'Checkpoint saved locally. Escape pauses the mission.'}</div>`);
  if(changed){save(true);world.setEVA(state.phase==='eva');if(state.phase==='eclipse')notify('Ines: Laboratory circuit tripped. Isolate it, collect a spare, then restore power.');}
 }
 function showPause(){if(view!=='play')return;paused=true;state.paused=true;world.setPaused(true);save();const overlay=root.querySelector('.cp-overlay');overlay.hidden=false;overlay.innerHTML=`<div class="cp-dialog"><small>MISSION PAUSED / ${CLOCK(state.elapsed)}</small><h2>TAKE A BREATH.</h2><p>Your spacecraft and mission clock are paused.</p>${button('RESUME MISSION','data-cp="resume"','cp-button cp-primary')}${button('RESTART FROM LAST CHECKPOINT','data-cp="checkpoint"')}${button('SAVE & MISSION SELECT','data-cp="save-select"')}${button('ABORT MISSION','data-cp="abort"','cp-quiet')}</div>`;mountPreferences(overlay.querySelector('.cp-dialog'));}
 function resume(){paused=false;state.paused=false;world?.setPaused(false);root.querySelector('.cp-overlay').hidden=true;last=performance.now();accumulator=0;}
 function debrief(){view='debrief';paused=true;world?.setPaused(true);const r=campaignReport(state);if(r.success&&!recorded){progress[state.missionId]={score:Math.max(Number(progress[state.missionId]?.score)||0,r.score),completed:true};store(PROGRESS_KEY,JSON.stringify(progress));recorded=true;}save();root.querySelector('.cp-hud').innerHTML='';const overlay=root.querySelector('.cp-overlay');overlay.hidden=false;overlay.innerHTML=`<main class="cp-debrief"><small>MISSION ${definition.number} / DEBRIEF</small><h1>${r.success?'WELCOME HOME,<br><em>CREW.</em>':state.phase==='aborted'?'MISSION<br><em>ABORTED.</em>':'LEARN. ADAPT.<br><em>FLY AGAIN.</em>'}</h1><div class="cp-debrief-stats"><div><b>${r.score}</b><span>MISSION SCORE</span></div><div><b>${Math.floor(r.science)} MB</b><span>SCIENCE RETURNED</span></div><div><b>${Math.round(r.minimumBattery)}%</b><span>MINIMUM BATTERY</span></div><div><b>${CLOCK(state.elapsed)}</b><span>PLAY TIME</span></div></div><div class="cp-brief-grid"><article class="cp-panel"><h2>Engineering review</h2>${r.feedback.map(x=>`<p>${esc(x)}</p>`).join('')}<p>${r.success&&state.missionId==='orbital'?'Restore the Observatory is now unlocked.':''}</p></article><article class="cp-panel"><h2>Mission record</h2><p>${state.returned?'✓':'○'} Crew recovered safely</p><p>${state.transmitted>=90?'✓':'○'} Required science received on Earth</p><p>${state.done.includes('restore')?'✓':'○'} Laboratory power restored</p>${state.missionId==='telescope'?`<p>${state.installed&&state.verified?'✓':'○'} Observatory instrument installed and crew returned</p>`:''}<p>${esc(definition.reference)}</p><a href="${definition.source}" target="_blank" rel="noopener">Explore the historical mission at NASA ↗</a></article></div><div class="cp-actions">${button('MISSION SELECT','data-cp="missions"','cp-button cp-primary')}${button('RECONFIGURE & RETRY','data-cp="reconfigure"')}${button('EXPORT MISSION REPORT','data-cp="export"')}</div></main>`;}
 function onClick(event){const b=event.target.closest?.('[data-campaign],[data-cp],[data-mission],[data-equipment],[data-task]');if(!b||b.disabled)return;if(b.hasAttribute('data-campaign')){event.preventDefault();event.stopPropagation();open();return;}if(!root.contains(b))return;event.preventDefault();const cmd=b.dataset.cp;
  if(b.dataset.mission){briefing(b.dataset.mission);return;}
  if(b.dataset.equipment){design[b.dataset.equipment]=b.dataset.value;renderDesign();return;}
  if(b.dataset.task){interact(b.dataset.task);return;}
  if(cmd==='exit'){exit();return;}if(cmd==='missions'){if(state&&!['complete','failed','aborted'].includes(state.phase))save();loadToken++;loading=false;world?.dispose();world=null;state=null;select();return;}
  if(cmd==='design'){renderDesign();return;}if(cmd==='board'){board();return;}if(cmd==='continue'){if(saved)board(saved);return;}if(cmd==='retry'){board(state);return;}
  if(cmd==='pause'){showPause();return;}if(cmd==='resume'){resume();return;}if(cmd==='checkpoint'){const restored=decodeSave(checkpoint);if(restored)board(restored);return;}
  if(cmd==='save-select'){save();world?.dispose();world=null;state=null;select();return;}if(cmd==='abort'){abortCampaign(state);debrief();return;}if(cmd==='reconfigure'){const id=state.missionId;world?.dispose();world=null;state=null;briefing(id);renderDesign();return;}
  if(cmd==='conserve'){state.conserve=!state.conserve;renderHUD();return;}if(cmd==='cancel-task'){state.activity=null;renderHUD();return;}
  if(cmd==='export'){const blob=new Blob([JSON.stringify({mission:definition.name,design:state.design,report:campaignReport(state),events:state.log},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='t-minus-'+state.missionId+'-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 }
 document.addEventListener('click',onClick,true);
 root.addEventListener('input',event=>{const el=event.target;if(el.dataset.tuning){tuning[el.dataset.tuning]=Number(el.value);el.nextElementSibling.textContent=el.value;}});
 root.addEventListener('change',event=>{if(event.target.hasAttribute('data-crew')){state.crewCommand=event.target.value;state.crewTimer=0;notify('Crew assignment updated.');}});
 addEventListener('keydown',event=>{if(root.hidden)return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();if(modal){repairClose?.();return;}if(view==='play'){if(paused)resume();else showPause();}}},true);
 addEventListener('blur',()=>{if(!root.hidden&&view==='play'&&!paused&&!modal)showPause();});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&!root.hidden&&view==='play'&&!paused&&!modal)showPause();});
 function frame(now){requestAnimationFrame(frame);const dt=Math.min(.1,Math.max(0,(now-last)/1000));last=now;if(root.hidden||view!=='play'||!state||!world)return;
  if(!paused&&!modal){accumulator+=dt;while(accumulator>=.05){if(state.activity&&(state.activity.room!==context.room||!context.near||(state.activity.id==='install'&&!context.atTelescope)||(state.activity.id==='ingress'&&!context.atAirlock))){state.activity=null;notify('Task cancelled: stay at its equipment station while working.');}tickCampaign(state,.05);accumulator-=.05;}saveTime+=dt;if(saveTime>=10){save();saveTime=0;}noticeTime=Math.max(0,noticeTime-dt);}
  world.tick(dt);hudTime+=dt;if(['complete','failed','aborted'].includes(state.phase)){debrief();return;}if(hudTime>=.3){hudTime=0;renderHUD();}
 }
 requestAnimationFrame(frame);
 api.campaign={open,exit,get state(){return state;},get world(){return world;},get view(){return view;},get isOpen(){return !root.hidden;}};
 return api.campaign;
}
